import{_ as t,h as i,i as a,c as d,v as l,p as T,x as r,m as n,e as p,S as c}from"./chunks/framework.Dvtg8yj2.js";const b=JSON.parse('{"title":"推理张量并行","description":"","frontmatter":{"title":"推理张量并行","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/infer-tp.md","filePath":"llm/infer-tp.md","lastUpdated":1788454257000}'),s={name:"llm/infer-tp.md"};function h(A,e,E,P,f,m){const o=i("Mermaid");return a(),d("div",null,[e[1]||(e[1]=l('<h1 id="推理张量并行" tabindex="-1">推理张量并行 <a class="header-anchor" href="#推理张量并行" aria-label="Permalink to &quot;推理张量并行&quot;">​</a></h1><div class="epigraph"><p>训练期大微批让层内 All-Reduce 算得过；decode 一步一个 token 时，同一条 All-Reduce 变成延迟税，张量并行度不能从预训练配置原样抄来。</p><footer>—— 对照 Shoeybi 等 Megatron-LM 的切法，以及 DistServe 对 intra-op 并行与 TTFT/TPOT 的讨论</footer></div><p><a href="/llm/tensor-parallel">张量并行</a> 的数学在推理里没有变：列并行接行并行，注意力按头切，用 All-Reduce 还原完整乘。变的是 roofline。Prefill 一次吃完提示，序列长、算力密，接近训练前向；decode 每步 batch 里每个请求只多一个 query token，算术强度掉到带宽墙，层内集合通信的<strong>启动延迟</strong>从可重叠的背景噪声变成步时间的主角。Zhong 等人的 DistServe 把 intra-operator 并行（即这里的 TP）写成：能缩短执行时间，尤其对 prefill 的 TTFT 有用，但要求 NVLink 一类高带宽，并且和 decode 的 batch、SLO 绑在一起。本篇只谈推理期怎么选 \\(T\\)，不重写 Megatron 的行列配对公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单卡放不下权重时，推理也必须切模型。候选有三条：复制（数据并行实例）、<a href="/llm/infer-pp">流水线</a>、张量并行。复制要求每卡一份完整权重；PP 在 decode 上气泡大；TP 能把一层矩阵切开、用通信换更短的单层计算。训练集群上 \\(T=8\\) 很常见，因为微批大、计算盖得住 All-Reduce。服务上若把同一 \\(T\\) 打到 decode 实例，每步两次（注意力输出、MLP 输出）跨卡同步，payload 只有 \\(b\\times 1\\times d\\)，带宽用不满，延迟按同步次数线性加。</p><p>GQA / <a href="/llm/mla">MLA</a> 还改了「按头切」的账。KV 头少于 \\(T\\) 时，要么无法整除，要么复制 KV 分片，TP 省下的 KV 内存被复制吃回。MLA 的潜向量若在 TP 组内每卡各持一份完整吸收投影，DeepSeek 服务侧会明确建议窄 TP、宽专家并行。问题是：prefill 与 decode 是否必须同一 \\(T\\)。</p><h3 id="prefill-与-decode-的-intra-op-动机不同" tabindex="-1">Prefill 与 decode 的 intra-op 动机不同 <a class="header-anchor" href="#prefill-与-decode-的-intra-op-动机不同" aria-label="Permalink to &quot;Prefill 与 decode 的 intra-op 动机不同&quot;">​</a></h3><p>DistServe 指出：提示不算太短时，prefill 接近 compute-bound，intra-op 能把 TTFT 的执行段切短，SLO 越紧越值得加 \\(T\\)。Decode 在小 batch 时是带宽墙，加 \\(T\\) 减少的是每卡要读的权重，这有利于步延迟，但 All-Reduce 次数不变（每层仍要同步）。\\(T\\) 增大，每卡 GEMM 更窄，更难喂饱 Tensor Core，通信占比上升。于是同一模型在 PD 分离之后，prefill 池可以用较大 \\(T\\) 换 TTFT，decode 池用较小 \\(T\\) 甚至 \\(T=1\\) 加复制，换 TPOT 与更简单的通信域。</p><p><span class="marginnote">「执行时间」不是端到端延迟。DistServe 强调延迟还包括排队。TP 缩短单次 prefill 执行，若因此能用更少卡达到 TTFT SLO，排队也会变；若盲目加 \\(T\\) 导致实例数变少，排队可能反而变长。选 \\(T\\) 要和复制数一起搜，不能单独调。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>推理 TP 仍落在 NVLink 域：节点内 2/4/8 卡一组。嵌入与 LM 头可按词表切。Decode 开启 CUDA Graph 时，All-Reduce 必须能进图，或整段 TP 通信用可捕获的内核；否则图捕获失败，步延迟回退。连续批处理把多个请求的单 token 拼成 \\(b&gt;1\\) 的 decode batch，All-Reduce 的 payload 变成 \\(b\\times d\\)，延迟占比下降——这是「decode 也能用较大 \\(T\\)」的主要条件。Batch 上不去时（显存被 KV 占满、或流量低），应降 \\(T\\)、换复制。</p><h3 id="与-gqa、mla、投机解码叠在一起" tabindex="-1">与 GQA、MLA、投机解码叠在一起 <a class="header-anchor" href="#与-gqa、mla、投机解码叠在一起" aria-label="Permalink to &quot;与 GQA、MLA、投机解码叠在一起&quot;">​</a></h3><p>GQA：KV 头数须能被 \\(T\\) 整除，否则 padding 或复制。MLA：潜在 KV 的切分不能假设「一头一卡」；开源栈常见注意力复制、专家走 EP，\\(T=1\\)。投机解码的验证步一次吃进树节点，序列宽度 \\(&gt;1\\)，瞬时更像一小段 prefill，TP 的计算通信比暂时变好；不能据此把 decode 稳态的 \\(T\\) 调到验证步的最优。验证步与普通 decode 步若共用同一并行度，应按稳态 TPOT 选，让验证步偶尔偏贵。</p>',13)),(a(),T(c,null,{default:r(()=>[p(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22Prefill%EF%BC%9A%E9%95%BF%E5%BA%8F%E5%88%97%EF%BC%8C%E5%81%8F%E8%AE%A1%E7%AE%97%E5%A2%99%22%5D%20--%3E%20TP1%5B%22%E5%8F%AF%E7%94%A8%E8%BE%83%E5%A4%A7%20T%20%E5%88%87%20TTFT%22%5D%0A%20%20D%5B%22Decode%EF%BC%9A%E5%8D%95%20token%EF%BC%8C%E5%81%8F%E5%B8%A6%E5%AE%BD%E5%A2%99%22%5D%20--%3E%20Q%7B%22%E8%BF%9E%E7%BB%AD%E6%89%B9%20b%20%E6%98%AF%E5%90%A6%E8%B6%B3%E5%A4%9F%22%7D%0A%20%20Q%20--%3E%7C%22b%20%E5%A4%A7%22%7C%20TP2%5B%22%E4%B8%AD%E7%AD%89%20T%EF%BC%8C%E9%80%9A%E4%BF%A1%20payload%20%E5%A4%9F%22%5D%0A%20%20Q%20--%3E%7C%22b%E2%89%881%22%7C%20R%5B%22%E9%99%8D%20T%20%E6%88%96%E5%A4%8D%E5%88%B6%EF%BC%8C%E9%81%BF%E5%85%8D%20All-Reduce%20%E5%BB%B6%E8%BF%9F%E7%A8%8E%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<h3 id="distserve-里与-inter-op-的分工" tabindex="-1">DistServe 里与 inter-op 的分工 <a class="header-anchor" href="#distserve-里与-inter-op-的分工" aria-label="Permalink to &quot;DistServe 里与 inter-op 的分工&quot;">​</a></h3><p>Intra-op 减执行时间、要高带宽；inter-op（流水线）几乎线性加吞吐、少减单请求执行时间。Prefill 在紧 TTFT 下偏向 intra-op；decode 在要拉大 batch、SLO 不太杀 TPOT 时偏向复制或流水线扩吞吐。PD 分离之后两阶段可以选不同组合：这是 colocated 服务做不到的——colocate 时同一组卡必须同时伺候两种 roofline。带宽不够跨节点时，TP 组绝不能跨机；那是训练里已经成立、推理里更成立的约束，因为 decode 更怕延迟。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>一次 decode 步的时间粗分为：读权重、本地 GEMM、All-Reduce、写 KV。\\(T\\) 把前两项摊到多卡，第三项加上 \\((T-1)\\) 相关的同步。当 GEMM 时间 \\(\\gg\\) 同步时间，\\(T\\) 有益；当 GEMM 已经只剩几十微秒，同步一次可能同量级甚至更大。Prefill 的 GEMM 按 \\(s\\) 放大，同步按激活体积 \\(b s d\\) 放大，但算术强度高，重叠更好。这就是「同一 \\(T\\)、两段寿命」的机制。</p><p>数值上 All-Reduce 求和顺序使不同 \\(T\\) 的 logits 非比特一致。服务一般不要求跨并行度比特复现，但 A/B 评测应固定 \\(T\\)。投机解码的拒绝采样对 logits 差敏感，TP 度改变若伴随非确定性通信，接受率会漂一截，调试时要先锁并行度再谈 <a href="/llm/spec-acceptance-rate">接受率</a>。</p><p><span class="marginnote">推理 TP 不减小每个请求看见的序列长度。它减小每卡隐藏宽与每卡权重。有人说「TP 之后上下文可以更长」——那是省下的权重显存让给了 KV；序列维没有被 TP 切开。切序列是上下文并行，另一条轴。</span></p><h3 id="显存与-kv" tabindex="-1">显存与 KV <a class="header-anchor" href="#显存与-kv" aria-label="Permalink to &quot;显存与 KV&quot;">​</a></h3><p>权重显存约 \\(\\Phi/T\\)。KV 在按头切的实现里也可除以 \\(T\\)，这是长上下文 decode 用 TP 的第二个理由。MLA 吸收后 KV 已经小，再 TP 切注意力收益变薄，还可能复制潜投影。规划时应写清：这次 TP 是为了放权重、为了切 KV，还是为了切 TTFT。三个目标对应三个最优 \\(T\\)，很少重合。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>小模型 \\(T=8\\) 几乎总是通信亏。70B 级在 2×80GB 上 \\(T=2\\) 常是放得下与同步可接受的折中。PD 分离后不要强制 P 实例与 D 实例同构：DistServe 的搜索空间就是让它们的 GPU 数与并行策略分开。Chunked-prefill 与 piggyback 是 colocate 下缓和干扰的办法，不是 TP 的替代；分离之后 chunked-prefill 的动机变弱，但 TP 仍在。</p><p>不要把训练的 sequence parallel 打开当推理默认：推理 decode 序列维是 1，切序列没有对象。也不要把专家并行的 All-to-All 算进 TP 的 All-Reduce 预算。NCCL 组必须分开。引用 Megatron 证明切法正确；引用 DistServe（arXiv:2401.09670）证明 prefill/decode 对 intra-op 的偏好不同。不要给「推理专用 TP 算法」伪造一篇不存在的 arXiv。</p><p><span class="marginnote">测 TP 加速比时用单步 decode 时间，不要用含 prefill 的端到端。TTFT 改善、TPOT 恶化是典型错配：说明 \\(T\\) 是按 prefill 选的，却打在了 decode 实例上。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>推理 TP 切法与训练相同，但 decode 小 batch 时 All-Reduce 延迟主导，不能照抄预训练 \\(T\\)。</li><li>Prefill 偏计算墙，紧 TTFT 可加大 intra-op；decode 要看连续批大小，batch 不够就降 \\(T\\) 或复制。</li><li>PD 分离允许两阶段使用不同 \\(T\\)；colocate 则被迫共用。</li><li>GQA/MLA 改变按头切与 KV 收益；投机验证步不能单独决定稳态 \\(T\\)。</li><li>权重、KV、TTFT 三个目标对应不同最优并行度。</li><li>出处：Shoeybi 等 Megatron-LM；Zhong et al., <em>DistServe</em>，OSDI 2024，arXiv:2401.09670。</li></ul>',14))])}const D=t(s,[["render",h]]);export{b as __pageData,D as default};
